const fs = require("fs");
function moduleDocstring(file) {
  const lines = fs.readFileSync(file, "utf8").split("\n");
  const out = [];
  for (const ln of lines) {
    const m = ln.match(/^\s*\/\/!(.*)$/);
    if (!m) break;
    out.push(m[1].replace(/^ /, ""));
  }
  return out.join("\n");
}
function parseFrontMatter(doc) {
  const lines = doc.split("\n");
  let i = lines.findIndex((l) => l.trim() === "```mlt");
  if (i === -1) return null;
  const kv = {};
  for (let j = i + 1; j < lines.length; j++) {
    const l = lines[j].trim();
    if (l === "```") break;
    const m = l.match(/^([A-Za-z_]+)\s*=\s*(.+)$/);
    if (!m) continue;
    let v = m[2].trim();
    if ((v.startsWith("\"") && v.endsWith("\"")) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    kv[m[1]] = v;
  }
  if (!kv.id) return null;
  return { id: kv.id, title: kv.title ?? kv.id, category: kv.category ?? "", severity: kv.severity ?? "warning", fix: (kv.fix ?? "false") === "true", icon: kv.icon, slug: kv.slug, data_file: kv.data_file, note: kv.note, generated: kv.generated, ...kv };
}
for (const f of ["crates/mlt_rules/src/naming.rs","crates/mlt_rules/src/compatibility/mod.rs","crates/mlt_rules/src/custom_checks.rs","crates/mlt_rules/src/suggested_improvements.rs","crates/mlt_rules/src/nosemi.rs"]) {
  const fm = parseFrontMatter(moduleDocstring(f));
  console.log(f, "=> fm.fix =", JSON.stringify(fm.fix), "truthy:", !!fm.fix, "render:", fm.fix ? "Yes" : "No");
}
'

